	if ! oum_is_installed; then
		printf '\nÐ¡Ð½Ð°Ñ‡Ð°Ð»Ð° ÑƒÑÑ‚Ð°Ð½Ð¾Ð²Ð¸Ñ‚Ðµ OUM, Ð²Ñ‹Ð±Ñ€Ð°Ð² Ð¿ÑƒÐ½ÐºÑ‚ 1.\n'
		return 0
	fi

	if [ "$(uci -q get oum.main.setup_complete || echo 0)" = '1' ]; then
		printf '\nÐŸÐµÑ€Ð²Ð¸Ñ‡Ð½Ð°Ñ Ð½Ð°ÑÑ‚Ñ€Ð¾Ð¹ÐºÐ° ÑƒÐ¶Ðµ Ð·Ð°Ð²ÐµÑ€ÑˆÐµÐ½Ð°.\n'
		printf 'ÐŸÐ¾Ð²Ñ‚Ð¾Ñ€Ð½Ñ‹Ð¹ Ð·Ð°Ð¿ÑƒÑÐº ÑƒÐ´Ð°Ð»Ð¸Ñ‚ Ñ‚ÐµÐºÑƒÑ‰Ð¸Ð¹ VPN-Ð¿Ñ€Ð¾Ñ„Ð¸Ð»ÑŒ, Ð²ÐºÐ»ÑŽÑ‡Ð¸Ñ‚ ÑÐµÑ‚ÑŒ FirstRun\n'
		printf 'Ð¸ Ð¼Ð¾Ð¶ÐµÑ‚ Ð¾Ð±Ð¾Ñ€Ð²Ð°Ñ‚ÑŒ Ñ‚ÐµÐºÑƒÑ‰ÐµÐµ Ð¿Ð¾Ð´ÐºÐ»ÑŽÑ‡ÐµÐ½Ð¸Ðµ Ðº Ñ€Ð¾ÑƒÑ‚ÐµÑ€Ñƒ.\n'
		oum_confirm 'Ð—Ð°Ð¿ÑƒÑÑ‚Ð¸Ñ‚ÑŒ Ð¼Ð°ÑÑ‚ÐµÑ€ Ð·Ð°Ð½Ð¾Ð²Ð¾?' || { printf 'Ð”ÐµÐ¹ÑÑ‚Ð²Ð¸Ðµ Ð¾Ñ‚Ð¼ÐµÐ½ÐµÐ½Ð¾.\n'; return 0; }
		/usr/libexec/oum-reset-first-run
	else
		printf '\nÐŸÐµÑ€Ð²Ñ‹Ð¹ Ð·Ð°Ð¿ÑƒÑÐº Ð²ÐºÐ»ÑŽÑ‡Ð¸Ñ‚ Wi-Fi ÑÐµÑ‚ÑŒ FirstRun Ð¸ Ð¼Ð¾Ð¶ÐµÑ‚ Ð¾Ð±Ð¾Ñ€Ð²Ð°Ñ‚ÑŒ Ñ‚ÐµÐºÑƒÑ‰ÐµÐµ Ð¿Ð¾Ð´ÐºÐ»ÑŽÑ‡ÐµÐ½Ð¸Ðµ.\n'
		oum_confirm 'ÐŸÑ€Ð¾Ð´Ð¾Ð»Ð¶Ð¸Ñ‚ÑŒ?' || { printf 'Ð”ÐµÐ¹ÑÑ‚Ð²Ð¸Ðµ Ð¾Ñ‚Ð¼ÐµÐ½ÐµÐ½Ð¾.\n'; return 0; }
		/usr/libexec/oum-firstboot
	fi

	printf '\nÐŸÐµÑ€Ð²Ñ‹Ð¹ Ð·Ð°Ð¿ÑƒÑÐº Ð¿Ð¾Ð´Ð³Ð¾Ñ‚Ð¾Ð²Ð»ÐµÐ½.\n'
	printf 'ÐŸÐ¾Ð´ÐºÐ»ÑŽÑ‡Ð¸Ñ‚ÐµÑÑŒ Ðº Wi-Fi FirstRun (Ð¿Ð°Ñ€Ð¾Ð»ÑŒ: admin123) Ð¸ Ð¾Ñ‚ÐºÑ€Ð¾Ð¹Ñ‚Ðµ 192.168.5.1.\n'
